const OPEN_TRANSLATE_DIALOG={name:"open-translate-dialog",action:function(e,t,a){let i=apex.region("IGTRANS").call("getCurrentView").model,l=i.getRecord(a.id);apex.item(a.id_item).setValue(a.id),apex.item(a.source_item).setValue(i.getValue(l,"SOURCE_TEXT")),apex.item(a.target_item).setValue(i.getValue(l,"TARGET_TEXT")),apex.theme.openRegion("TRANSLATE")}},CLOSE_TRANSLATE_DIALOG={name:"close-translate-dialog",action:function(e,t,a){let i=apex.region("IGTRANS").call("getCurrentView").model,l=i.getRecord(apex.item(a.id_item).getValue());i.setValue(l,"TARGET_TEXT",apex.item(a.target_item).getValue()),apex.theme.closeRegion("TRANSLATE")}};